    SELECT id INTO v_wh_id FROM public.warehouses WHERE company_id = v_company_id AND (code = 'MSM' OR name = 'Main Store Mesaieed') LIMIT 1;
    IF v_wh_id IS NULL THEN
        INSERT INTO public.warehouses (id, company_id, name, code, address, is_active)
        VALUES (gen_random_uuid(), v_company_id, 'Main Store Mesaieed', 'MSM', 'Mesaieed Industrial City, Qatar', true)
        RETURNING id INTO v_wh_id;
    END IF;

    -- 2. Ensure General Storage Zone exists
    SELECT id INTO v_zone_id FROM public.warehouse_zones WHERE warehouse_id = v_wh_id AND code = 'ZONE-A' LIMIT 1;
    IF v_zone_id IS NULL THEN
        INSERT INTO public.warehouse_zones (id, company_id, warehouse_id, name, code, zone_type)
        VALUES (gen_random_uuid(), v_company_id, v_wh_id, 'General Storage Zone', 'ZONE-A', 'STORAGE')
        RETURNING id INTO v_zone_id;
    END IF;

    -- 3. Ensure Main Bin exists
    SELECT id INTO v_bin_id FROM public.warehouse_bins WHERE zone_id = v_zone_id AND code = 'BIN-01' LIMIT 1;
    IF v_bin_id IS NULL THEN
        INSERT INTO public.warehouse_bins (id, company_id, zone_id, name, code, is_active)
        VALUES (gen_random_uuid(), v_company_id, v_zone_id, 'Main Bin A-01', 'BIN-01', true)
        RETURNING id INTO v_bin_id;
    END IF;

    -- 4. Clean any prior opening stock transactions to ensure clean idempotent run
    DELETE FROM public.inventory_transactions WHERE company_id = v_company_id AND reference_type = 'OPENING_STOCK';
    DELETE FROM public.stock_movements WHERE company_id = v_company_id AND reference_type = 'OPENING_STOCK';

    -- 5. Loop over all 216 items
    FOR r IN SELECT * FROM jsonb_to_recordset(v_data) AS x(
        code text,
        name text,
        category text,
        uom text,
        qty numeric,
        rate numeric,
        total numeric
    )
    LOOP
        SELECT id INTO v_item_id FROM public.item_master 
        WHERE company_id = v_company_id AND (code = r.code OR name = r.name) 
        LIMIT 1;

        IF v_item_id IS NULL THEN
            INSERT INTO public.item_master (
                id, company_id, code, name, category, uom, standard_cost, is_stockable, status
            ) VALUES (
                gen_random_uuid(), v_company_id, r.code, r.name, r.category, r.uom, r.rate, true, 'Active'
            ) RETURNING id INTO v_item_id;
        ELSE
            UPDATE public.item_master
            SET category = r.category,
                uom = r.uom,
                standard_cost = r.rate,
                is_stockable = true,
                status = 'Active'
            WHERE id = v_item_id;
        END IF;

        INSERT INTO public.inventory_transactions (
            company_id, posting_date, transaction_type, item_id, warehouse_id, quantity, unit_cost, reference_type
        ) VALUES (
            v_company_id, '2026-08-01', 'OPENING_BALANCE', v_item_id, v_wh_id, r.qty, (r.total / r.qty), 'OPENING_STOCK'
        );

        INSERT INTO public.stock_movements (
            company_id, created_at, item_id, movement_type, quantity, to_bin_id, reference_type
        ) VALUES (
            v_company_id, '2026-08-01 00:00:00+00', v_item_id, 'IN', r.qty, v_bin_id, 'OPENING_STOCK'
        );
    END LOOP;
END;
$$;
